import React, { useMemo, useState } from "react";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";
import axios from "axios";
import { API_BASE_URL } from "../config";
import { useHematrikData } from "../data/HematrikDataContext";
import { getStatusColor } from "../utils/statusColors";
import Toggle from "../components/ui/Toggle";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

export default function DashboardPage() {
  const { data, latest, loading, dashboard, devices, summary, reload } = useHematrikData();
  const [deviceSaving, setDeviceSaving] = useState(false);
  const [deviceError, setDeviceError] = useState(null);

  const notifications = dashboard?.notifications ?? [];

  const deviceView = {
    status_listrik: devices?.status_listrik ?? latest?.status_listrik,
    lampu: devices?.lampu ?? latest?.lampu,
    ac: devices?.ac ?? latest?.ac,
    dispenser: devices?.dispenser ?? latest?.dispenser,
  };

  const chartData = useMemo(
    () => {
      const activity = dashboard?.activity_7d ?? [];
      return {
        labels:
          activity.length > 0
            ? activity.map((d) => d.tanggal)
            : data.map((d) => d.waktu).slice(-10),
        datasets: [
          {
            label: activity.length > 0 ? "Rata-rata Orang (7 hari)" : "Jumlah Orang",
            data:
              activity.length > 0
                ? activity.map((d) => d.avg_orang)
                : data.map((d) => d.jumlah_orang).slice(-10),
            borderColor: "#22c55e",
            tension: 0.4
          }
        ]
      };
    },
    [dashboard, data]
  );

  if (loading) return <div className="loading">Loading data...</div>;
  if (!latest) return <div className="loading">No data yet.</div>;

  const setDevice = async (patch) => {
    setDeviceSaving(true);
    setDeviceError(null);
    try {
      await axios.post(`${API_BASE_URL}/devices`, patch);
      // Refresh from server so UI matches DB-persisted state.
      await reload();
    } catch (e) {
      setDeviceError("Gagal menyimpan status perangkat.");
    } finally {
      setDeviceSaving(false);
    }
  };

  return (
    <>
      <div className="banner" style={{ borderLeftColor: getStatusColor(latest.kondisi) }}>
        <div className="banner__label">Status</div>
        <div className="banner__text">{latest.notifikasi}</div>
      </div>

      <section className="grid">
        <div className="card">
          <div className="card__title">People Detected</div>
          <div className="card__value">{latest.jumlah_orang}</div>
        </div>

        <div className="card">
          <div className="card__title">Room Activity</div>
          <div className="card__value">
            <span className="pill pill--muted">{latest.kondisi}</span>
          </div>
          <div className="card__meta" style={{ color: getStatusColor(latest.kondisi) }}>
            {latest.kondisi}
          </div>
        </div>

        <div className="card">
          <div className="card__title">Device Status</div>
          <div className="device">
            <div className="device__row">
              <div className="device__name">Listrik</div>
              <div
                className={
                  deviceView.status_listrik === "ON"
                    ? "device__state device__state--on"
                    : "device__state device__state--off"
                }
              >
                {deviceView.status_listrik ?? "-"}
              </div>
            </div>

            <div className="device__row">
              <div className="device__name">Lampu</div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div
                  className={
                    String(deviceView.lampu).toUpperCase() === "ON"
                      ? "device__state device__state--on"
                      : "device__state device__state--off"
                  }
                >
                  {deviceView.lampu ?? "-"}
                </div>
                <Toggle
                  label=""
                  checked={String(deviceView.lampu).toUpperCase() === "ON"}
                  disabled={deviceSaving}
                  onChange={(v) => setDevice({ lampu: v ? "ON" : "OFF" })}
                />
              </div>
            </div>

            <div className="device__row">
              <div className="device__name">AC</div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div
                  className={
                    String(deviceView.ac).toUpperCase() === "ON"
                      ? "device__state device__state--on"
                      : "device__state device__state--off"
                  }
                >
                  {deviceView.ac ?? "-"}
                </div>
                <Toggle
                  label=""
                  checked={String(deviceView.ac).toUpperCase() === "ON"}
                  disabled={deviceSaving}
                  onChange={(v) => setDevice({ ac: v ? "ON" : "OFF" })}
                />
              </div>
            </div>

            <div className="device__row">
              <div className="device__name">Dispenser</div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div
                  className={
                    String(deviceView.dispenser).toUpperCase() === "ON"
                      ? "device__state device__state--on"
                      : "device__state device__state--off"
                  }
                >
                  {deviceView.dispenser ?? "-"}
                </div>
                <Toggle
                  label=""
                  checked={String(deviceView.dispenser).toUpperCase() === "ON"}
                  disabled={deviceSaving}
                  onChange={(v) => setDevice({ dispenser: v ? "ON" : "OFF" })}
                />
              </div>
            </div>
            <div className="device__hint">
              Updated: {latest.waktu}
              {deviceError ? ` • ${deviceError}` : deviceSaving ? " • Menyimpan…" : ""}
            </div>
          </div>
        </div>

        <div className="card">
          <div className="card__title">Ringkasan Bulan Ini</div>
          {summary?.monthly ? (
            <>
              <div className="card__value">{summary.monthly.total_pengecekan ?? 0}</div>
              <div className="card__meta">
                Normal: {summary.monthly.normal ?? 0} • Pemborosan: {summary.monthly.pemborosan ?? 0} • Peringatan:{" "}
                {summary.monthly.peringatan ?? 0} • Aman: {summary.monthly.aman ?? 0}
              </div>
            </>
          ) : (
            <div className="card__meta">Belum ada data ringkasan.</div>
          )}
        </div>
      </section>

      <section className="card card--chart">
        <div className="card__title">Room Activity</div>
        <div className="chart">
          <Line data={chartData} />
        </div>
      </section>

      <section className="card" style={{ marginTop: 14 }}>
        <div className="card__title">Notifikasi Terbaru</div>
        {notifications.length === 0 ? (
          <div className="card__meta">Belum ada notifikasi.</div>
        ) : (
          <div className="tableWrap">
            <table className="table">
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Kondisi</th>
                  <th>Notifikasi</th>
                </tr>
              </thead>
              <tbody>
                {notifications.map((n) => (
                  <tr key={n.id ?? `${n.waktu}-${n.kondisi}`}> 
                    <td>{n.waktu}</td>
                    <td style={{ color: getStatusColor(n.kondisi) }}>{n.kondisi}</td>
                    <td>{n.notifikasi}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </>
  );
}
